113	function cleanDocs() {
114	  const cwd = process.cwd();
115	  let removed = 0;
116	  for (const file of DOC_FILENAMES) {
117	    const target = path.join(cwd, file);
118	    if (fs.existsSync(target)) {
119	      fs.unlinkSync(target);
120	      removed += 1;
121	      log.info(`Removed ${file}`);
122	    }
123	  }
124	  if (!removed) {
125	    log.info('No documentation files to remove.');
126	  } else {
127	    log.success('Documentation directory cleaned.', { removed });
128	  }
129	}
