513	function runFinetuneTemplateCommand(options: FinetuneTemplateOptions) {
514	  const template = Finetune.createGovernanceTemplate();
515	  const target = options.output ? path.resolve(options.output) : path.resolve(process.cwd(), 'frai-finetune-plan.json');
516	  fs.writeFileSync(target, JSON.stringify(template, null, 2), 'utf8');
517	  log.success('Fine-tuning governance template written.', { path: target });
518	}
519	
520	function runFinetuneValidateCommand(planPath: string, options: FinetuneValidateOptions) {
521	  const absolute = path.resolve(planPath);
522	  assertFileExists(absolute);
523	  const raw = fs.readFileSync(absolute, 'utf8');
524	  let parsed: unknown;
525	  try {
526	    parsed = JSON.parse(raw);
527	  } catch (error) {
528	    throw new Error(`Invalid JSON: ${(error as Error).message}`);
529	  }
530	  const validation = Finetune.validateGovernancePlan(parsed);
531	  if (!validation.valid) {
532	    log.error('Fine-tuning governance plan is invalid.');
533	    validation.errors.forEach((errorItem) => {
534	      console.error(` - ${errorItem.path}: ${errorItem.message}`);
535	    });
536	  } else {
537	    log.success('Fine-tuning governance plan is valid.');
538	  }
539	
540	  if (options.readiness) {
541	    const readiness = Finetune.calculateReadiness(parsed as Parameters<typeof Finetune.calculateReadiness>[0]);
542	    log.info('Readiness checkpoint status', readiness);
543	    console.log(Finetune.summarizeGovernance(parsed as Parameters<typeof Finetune.calculateReadiness>[0]));
544	  }
545	}
