// Simple test of threshold parsing logic
function parseThresholds(thresholdStrings) {
  if (!thresholdStrings || thresholdStrings.length === 0) {
    return undefined;
  }

  const validMetricIds = ['exact_match', 'toxicity', 'length_variance'];
  const thresholds = {};

  for (const thresholdStr of thresholdStrings) {
    const match = thresholdStr.match(/^([a-z_]+)=([0-9.]+)$/);
    if (!match) {
      throw new Error(`Malformed threshold: ${thresholdStr}. Expected format: <metric>=<number>`);
    }

    const [, metricId, minStr] = match;
    const min = Number.parseFloat(minStr);

    if (!validMetricIds.includes(metricId)) {
      throw new Error(`Unknown metric id: ${metricId}`);
    }

    if (Number.isNaN(min) || min < 0 || min > 1) {
      throw new Error(`Threshold minimum must be a number between 0 and 1, got: ${minStr}`);
    }

    thresholds[metricId] = min;
  }

  return thresholds;
}

// Test cases
console.log('Test 1: No thresholds');
console.log(parseThresholds([]));
console.log(parseThresholds(undefined));
console.log('');

console.log('Test 2: Valid single threshold');
console.log(parseThresholds(['exact_match=0.9']));
console.log('');

console.log('Test 3: Valid multiple thresholds');
console.log(parseThresholds(['exact_match=0.9', 'toxicity=0.8']));
console.log('');

console.log('Test 4: Malformed threshold');
try {
  parseThresholds(['exact_match']);
  console.log('ERROR: Should have thrown');
} catch (e) {
  console.log('Caught:', e.message);
}
console.log('');

console.log('Test 5: Unknown metric');
try {
  parseThresholds(['unknown_metric=0.5']);
  console.log('ERROR: Should have thrown');
} catch (e) {
  console.log('Caught:', e.message);
}
console.log('');

console.log('Test 6: Invalid number');
try {
  parseThresholds(['exact_match=abc']);
  console.log('ERROR: Should have thrown');
} catch (e) {
  console.log('Caught:', e.message);
}
console.log('');

console.log('Test 7: Number out of range');
try {
  parseThresholds(['exact_match=1.5']);
  console.log('ERROR: Should have thrown');
} catch (e) {
  console.log('Caught:', e.message);
}
console.log('');

console.log('Test 8: Negative number');
try {
  parseThresholds(['exact_match=-0.1']);
  console.log('ERROR: Should have thrown');
} catch (e) {
  console.log('Caught:', e.message);
}

