import fs from 'fs';
import os from 'os';
import path from 'path';
import { generateReport, runEvaluations, writeReport } from './packages/frai-core/src/eval/index.js';
import { toMarkdown, toJson } from './packages/frai-core/src/eval/reporters.js';

const tmpDir = fs.mkdtempSync(path.join(os.tmpdir(), 'frai-test-'));

function test(name, fn) {
  try {
    fn();
    console.log(`✓ ${name}`);
  } catch (error) {
    console.error(`✗ ${name}`);
    console.error(`  ${error.message}`);
    process.exit(1);
  }
}

function assertEqual(actual, expected, message) {
  if (actual !== expected) {
    throw new Error(`${message}: expected ${expected}, got ${actual}`);
  }
}

function assertTrue(value, message) {
  if (!value) {
    throw new Error(message);
  }
}

function assertFalse(value, message) {
  if (value) {
    throw new Error(message);
  }
}

// Test 1: Without thresholds, passed should be true
test('Without thresholds, passed is true', () => {
  const evaluations = runEvaluations({
    outputs: ['Hello'],
    references: ['hello']
  });
  const report = generateReport({
    evaluations,
    outputsPath: '/tmp/outputs.json',
    referencesPath: '/tmp/refs.json'
  });
  assertTrue(report.passed, 'passed should be true when no thresholds');
  assertFalse(report.thresholds, 'thresholds should not exist when none provided');
});

// Test 2: All thresholds pass
test('All thresholds pass', () => {
  const evaluations = runEvaluations({
    outputs: ['Hello'],
    references: ['hello']
  });
  const report = generateReport({
    evaluations,
    outputsPath: '/tmp/outputs.json',
    referencesPath: '/tmp/refs.json',
    thresholds: { exact_match: 0.5 }
  });
  assertTrue(report.passed, 'passed should be true when thresholds pass');
  assertTrue(Array.isArray(report.thresholds), 'thresholds should be an array');
  assertEqual(report.thresholds.length, 1, 'should have 1 threshold');
  assertEqual(report.thresholds[0].metric, 'exact_match', 'metric should be exact_match');
  assertEqual(report.thresholds[0].min, 0.5, 'min should be 0.5');
