import fs from 'fs';
import os from 'os';
import path from 'path';
import { generateReport, runEvaluations, writeReport } from './packages/frai-core/src/eval/index.js';
import { toMarkdown, toJson } from './packages/frai-core/src/eval/reporters.js';

const tmpDir = fs.mkdtempSync(path.join(os.tmpdir(), 'frai-test-'));

function test(name, fn) {
  try {
    fn();
    console.log(`✓ ${name}`);
  } catch (error) {
    console.error(`✗ ${name}`);
    console.error(`  ${error.message}`);
    process.exit(1);
  }
}

function assertEqual(actual, expected, message) {
  if (actual !== expected) {
    throw new Error(`${message}: expected ${expected}, got ${actual}`);
  }
}

function assertTrue(value, message) {
  if (!value) {
    throw new Error(message);
  }
}

function assertFalse(value, message) {
  if (value) {
    throw new Error(message);
  }
}

// Test 1: Without thresholds, passed should be true
test('Without thresholds, passed is true', () => {
  const evaluations = runEvaluations({
    outputs: ['Hello'],
    references: ['hello']
  });
  const report = generateReport({
    evaluations,
    outputsPath: '/tmp/outputs.json',
    referencesPath: '/tmp/refs.json'
  });
  assertTrue(report.passed, 'passed should be true when no thresholds');
  assertFalse(report.thresholds, 'thresholds should not exist when none provided');
});

// Test 2: All thresholds pass
test('All thresholds pass', () => {
  const evaluations = runEvaluations({
    outputs: ['Hello'],
    references: ['hello']
  });
  const report = generateReport({
    evaluations,
    outputsPath: '/tmp/outputs.json',
    referencesPath: '/tmp/refs.json',
    thresholds: { exact_match: 0.5 }
  });
  assertTrue(report.passed, 'passed should be true when thresholds pass');
  assertTrue(Array.isArray(report.thresholds), 'thresholds should be an array');
  assertEqual(report.thresholds.length, 1, 'should have 1 threshold');
  assertEqual(report.thresholds[0].metric, 'exact_match', 'metric should be exact_match');
  assertEqual(report.thresholds[0].min, 0.5, 'min should be 0.5');
  assertEqual(report.thresholds[0].score, 1, 'score should be 1');
  assertTrue(report.thresholds[0].passed, 'threshold should pass');
});

// Test 3: Some thresholds fail
test('Some thresholds fail', () => {
  const evaluations = runEvaluations({
    outputs: ['Hello'],
    references: ['goodbye']
  });
  const report = generateReport({
    evaluations,
    outputsPath: '/tmp/outputs.json',
    referencesPath: '/tmp/refs.json',
    thresholds: { exact_match: 0.9 }
  });
  assertFalse(report.passed, 'passed should be false when thresholds fail');
  assertFalse(report.thresholds[0].passed, 'threshold should fail');
});

// Test 4: Multiple thresholds, all pass
test('Multiple thresholds all pass', () => {
  const evaluations = runEvaluations({
    outputs: ['Hello'],
    references: ['hello']
  });
  const report = generateReport({
    evaluations,
    outputsPath: '/tmp/outputs.json',
    referencesPath: '/tmp/refs.json',
    thresholds: { exact_match: 0.5, length_variance: 0.5 }
  });
  assertTrue(report.passed, 'passed should be true when all thresholds pass');
  assertEqual(report.thresholds.length, 2, 'should have 2 thresholds');
});

// Test 5: Multiple thresholds, some fail
test('Multiple thresholds, some fail', () => {
  const evaluations = runEvaluations({
    outputs: ['Goodbye'],
    references: ['hello']
  });
  const report = generateReport({
    evaluations,
    outputsPath: '/tmp/outputs.json',
    referencesPath: '/tmp/refs.json',
    thresholds: { exact_match: 0.5, length_variance: 0.5 }
  });
  assertFalse(report.passed, 'passed should be false when any threshold fails');
  assertEqual(report.thresholds.length, 2, 'should have 2 thresholds');
  assertFalse(report.thresholds[0].passed, 'exact_match should fail with mismatched text');
  assertTrue(report.thresholds[1].passed, 'length_variance should pass');
});

// Test 6: Metric with no score fails threshold
test('Metric with no score fails threshold', () => {
  const evaluations = runEvaluations({
    outputs: ['Hello'],
    references: [] // No references, so exact_match will have no score
  });
  const report = generateReport({
    evaluations,
    outputsPath: '/tmp/outputs.json',
    referencesPath: '/tmp/refs.json',
    thresholds: { exact_match: 0.5 }
  });
  assertFalse(report.passed, 'passed should be false when metric has no score');
  assertFalse(report.thresholds[0].passed, 'threshold should fail when score is null');
  assertEqual(report.thresholds[0].score, null, 'score should be null');
});

// Test 7: JSON report includes thresholds
test('JSON report includes thresholds', () => {
  const evaluations = runEvaluations({
    outputs: ['Hello'],
    references: ['hello']
  });
  const report = generateReport({
    evaluations,
    outputsPath: '/tmp/outputs.json',
    referencesPath: '/tmp/refs.json',
    thresholds: { exact_match: 0.9 }
  });
  const json = toJson(report);
  const parsed = JSON.parse(json);
  assertTrue(parsed.passed !== undefined, 'JSON should include passed field');
  assertTrue(Array.isArray(parsed.thresholds), 'JSON should include thresholds array');
});

// Test 8: Markdown report includes thresholds section
test('Markdown report includes thresholds section', () => {
  const evaluations = runEvaluations({
    outputs: ['Hello'],
    references: ['hello']
  });
  const report = generateReport({
    evaluations,
    outputsPath: '/tmp/outputs.json',
    referencesPath: '/tmp/refs.json',
    thresholds: { exact_match: 0.5, length_variance: 0.99 }
  });
  const markdown = toMarkdown(report);
  assertTrue(markdown.includes('## Thresholds'), 'Markdown should include Thresholds section');
  assertTrue(markdown.includes('exact_match'), 'Markdown should mention exact_match metric');
  assertTrue(markdown.includes('length_variance'), 'Markdown should mention length_variance metric');
  assertTrue(markdown.includes('PASS'), 'Markdown should show PASS for passing thresholds');
  assertTrue(markdown.includes('FAIL'), 'Markdown should show FAIL for failing thresholds');
});

// Test 9: Markdown report without thresholds doesn't have thresholds section
test('Markdown report without thresholds has no thresholds section', () => {
  const evaluations = runEvaluations({
    outputs: ['Hello'],
    references: ['hello']
  });
  const report = generateReport({
    evaluations,
    outputsPath: '/tmp/outputs.json',
    referencesPath: '/tmp/refs.json'
  });
  const markdown = toMarkdown(report);
  assertFalse(markdown.includes('## Thresholds'), 'Markdown should not include Thresholds section when no thresholds');
});

// Test 10: Report is written with thresholds
test('Report is written with thresholds', () => {
  const evaluations = runEvaluations({
    outputs: ['Hello'],
    references: ['hello']
  });
  const report = generateReport({
    evaluations,
    outputsPath: '/tmp/outputs.json',
    referencesPath: '/tmp/refs.json',
    thresholds: { exact_match: 0.9 }
  });
  const reportPath = path.join(tmpDir, 'test-report.json');
  const written = writeReport({
    report,
    format: 'json',
    reportPath
  });
  assertTrue(fs.existsSync(written), 'Report file should exist');
  const content = JSON.parse(fs.readFileSync(written, 'utf8'));
  assertTrue(content.passed !== undefined, 'Report should include passed field');
  assertTrue(Array.isArray(content.thresholds), 'Report should include thresholds array');
});

console.log('\n✅ All tests passed!');

// Cleanup
fs.rmSync(tmpDir, { recursive: true, force: true });

